mkitem!{mkstruct!{# [doc = " `MovePath` is a canonicalized representation of a path that is"] # [doc = " moved or assigned to."] # [doc = ""] # [doc = " It follows a tree structure."] # [doc = ""] # [doc = " Given `struct X { m: M, n: N }` and `x: X`, moves like `drop x.m;`"] # [doc = " move *out* of the place `x.m`."] # [doc = ""] # [doc = " The MovePaths representing `x.m` and `x.n` are siblings (that is,"] # [doc = " one of them will link to the other via the `next_sibling` field,"] # [doc = " and the other will have no entry in its `next_sibling` field), and"] # [doc = " they both have the MovePath representing `x` as their parent."] # [derive (Clone)] pub struct MovePath < 'tcx > { pub next_sibling : Option < MovePathIndex > , pub first_child : Option < MovePathIndex > , pub parent : Option < MovePathIndex > , pub place : Place < 'tcx > , }}}
mkitem!{mkimpl!{impl < 'tcx > MovePath < 'tcx > { # [doc = " Returns an iterator over the parents of `self`."] pub fn parents < 'a > (& self , move_paths : & 'a IndexSlice < MovePathIndex , MovePath < 'tcx > > ,) -> impl 'a + Iterator < Item = (MovePathIndex , & 'a MovePath < 'tcx >) > { let first = self . parent . map (| mpi | (mpi , & move_paths [mpi])) ; MovePathLinearIter { next : first , fetch_next : move | _ , parent : & MovePath < '_ > | { parent . parent . map (| mpi | (mpi , & move_paths [mpi])) } , } } # [doc = " Returns an iterator over the immediate children of `self`."] pub fn children < 'a > (& self , move_paths : & 'a IndexSlice < MovePathIndex , MovePath < 'tcx > > ,) -> impl 'a + Iterator < Item = (MovePathIndex , & 'a MovePath < 'tcx >) > { let first = self . first_child . map (| mpi | (mpi , & move_paths [mpi])) ; MovePathLinearIter { next : first , fetch_next : move | _ , child : & MovePath < '_ > | { child . next_sibling . map (| mpi | (mpi , & move_paths [mpi])) } , } } # [doc = " Finds the closest descendant of `self` for which `f` returns `true` using a breadth-first"] # [doc = " search."] # [doc = ""] # [doc = " `f` will **not** be called on `self`."] pub fn find_descendant (& self , move_paths : & IndexSlice < MovePathIndex , MovePath < '_ > > , f : impl Fn (MovePathIndex) -> bool ,) -> Option < MovePathIndex > { let mut todo = if let Some (child) = self . first_child { vec ! [child] } else { return None ; } ; while let Some (mpi) = todo . pop () { if f (mpi) { return Some (mpi) ; } let move_path = & move_paths [mpi] ; if let Some (child) = move_path . first_child { todo . push (child) ; } if let Some (sibling) = move_path . next_sibling { todo . push (sibling) ; } } None } }}}
mkitem!{mkimpl!{impl < 'tcx > fmt :: Debug for MovePath < 'tcx > { fn fmt (& self , w : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (w , "MovePath {{") ? ; if let Some (parent) = self . parent { write ! (w , " parent: {parent:?},") ? ; } if let Some (first_child) = self . first_child { write ! (w , " first_child: {first_child:?},") ? ; } if let Some (next_sibling) = self . next_sibling { write ! (w , " next_sibling: {next_sibling:?}") ? ; } write ! (w , " place: {:?} }}" , self . place) } }}}
mkitem!{mkimpl!{impl < 'tcx > fmt :: Display for MovePath < 'tcx > { fn fmt (& self , w : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (w , "{:?}" , self . place) } }}}
mkitem!{mkstruct!{struct MovePathLinearIter < 'a , 'tcx , F > { next : Option < (MovePathIndex , & 'a MovePath < 'tcx >) > , fetch_next : F , }}}
mkitem!{mkimpl!{impl < 'a , 'tcx , F > Iterator for MovePathLinearIter < 'a , 'tcx , F > where F : FnMut (MovePathIndex , & 'a MovePath < 'tcx >) -> Option < (MovePathIndex , & 'a MovePath < 'tcx >) > , { type Item = (MovePathIndex , & 'a MovePath < 'tcx >) ; fn next (& mut self) -> Option < Self :: Item > { let ret = self . next . take () ? ; self . next = (self . fetch_next) (ret . 0 , ret . 1) ; Some (ret) } }}}
mkitem!{mkstruct!{# [derive (Debug)] pub struct MoveData < 'tcx > { pub move_paths : IndexVec < MovePathIndex , MovePath < 'tcx > > , pub moves : IndexVec < MoveOutIndex , MoveOut > , # [doc = " Each Location `l` is mapped to the MoveOut's that are effects"] # [doc = " of executing the code at `l`. (There can be multiple MoveOut's"] # [doc = " for a given `l` because each MoveOut is associated with one"] # [doc = " particular path being moved.)"] pub loc_map : LocationMap < SmallVec < [MoveOutIndex ; 4] > > , pub path_map : IndexVec < MovePathIndex , SmallVec < [MoveOutIndex ; 4] > > , pub rev_lookup : MovePathLookup < 'tcx > , pub inits : IndexVec < InitIndex , Init > , # [doc = " Each Location `l` is mapped to the Inits that are effects"] # [doc = " of executing the code at `l`."] pub init_loc_map : LocationMap < SmallVec < [InitIndex ; 4] > > , pub init_path_map : IndexVec < MovePathIndex , SmallVec < [InitIndex ; 4] > > , }}}
