mkitem!{mkstruct!{# [doc = " `MoveOut` represents a point in a program that moves out of some"] # [doc = " L-value; i.e., \"creates\" uninitialized memory."] # [doc = ""] # [doc = " With respect to dataflow analysis:"] # [doc = " - Generated by moves and declaration of uninitialized variables."] # [doc = " - Killed by assignments to the memory."] # [derive (Copy , Clone)] pub struct MoveOut { # [doc = " path being moved"] pub path : MovePathIndex , # [doc = " location of move"] pub source : Location , }}}
mkitem!{mkimpl!{impl fmt :: Debug for MoveOut { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (fmt , "{:?}@{:?}" , self . path , self . source) } }}}
mkitem!{mkstruct!{# [doc = " `Init` represents a point in a program that initializes some L-value;"] # [derive (Copy , Clone)] pub struct Init { # [doc = " path being initialized"] pub path : MovePathIndex , # [doc = " location of initialization"] pub location : InitLocation , # [doc = " Extra information about this initialization"] pub kind : InitKind , }}}
mkitem!{mkenum!{# [doc = " Initializations can be from an argument or from a statement. Arguments"] # [doc = " do not have locations, in those cases the `Local` is kept.."] # [derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum InitLocation { Argument (Local) , Statement (Location) , }}}
mkitem!{mkenum!{# [doc = " Additional information about the initialization."] # [derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum InitKind { # [doc = " Deep init, even on panic"] Deep , # [doc = " Only does a shallow init"] Shallow , # [doc = " This doesn't initialize the variable on panic (and a panic is possible)."] NonPanicPathOnly , }}}
mkitem!{mkimpl!{impl fmt :: Debug for Init { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (fmt , "{:?}@{:?} ({:?})" , self . path , self . location , self . kind) } }}}
mkitem!{mkimpl!{impl Init { pub fn span < 'tcx > (& self , body : & Body < 'tcx >) -> Span { match self . location { InitLocation :: Argument (local) => body . local_decls [local] . source_info . span , InitLocation :: Statement (location) => body . source_info (location) . span , } } }}}
mkitem!{mkstruct!{# [doc = " Tables mapping from a place to its MovePathIndex."] # [derive (Debug)] pub struct MovePathLookup < 'tcx > { locals : IndexVec < Local , Option < MovePathIndex > > , # [doc = " projections are made from a base-place and a projection"] # [doc = " elem. The base-place will have a unique MovePathIndex; we use"] # [doc = " the latter as the index into the outer vector (narrowing"] # [doc = " subsequent search so that it is solely relative to that"] # [doc = " base-place). For the remaining lookup, we map the projection"] # [doc = " elem to the associated MovePathIndex."] projections : FxHashMap < (MovePathIndex , ProjectionKind) , MovePathIndex > , un_derefer : UnDerefer < 'tcx > , }}}
