mkitem!{mkenum!{# [derive (Copy , Clone , Debug)] pub enum LookupResult { Exact (MovePathIndex) , Parent (Option < MovePathIndex >) , }}}
mkitem!{mkimpl!{impl < 'tcx > MovePathLookup < 'tcx > { pub fn find (& self , place : PlaceRef < 'tcx >) -> LookupResult { let Some (mut result) = self . find_local (place . local) else { return LookupResult :: Parent (None) ; } ; for (_ , elem) in self . un_derefer . iter_projections (place) { if let Some (& subpath) = self . projections . get (& (result , elem . kind ())) { result = subpath ; } else { return LookupResult :: Parent (Some (result)) ; } } LookupResult :: Exact (result) } # [inline] pub fn find_local (& self , local : Local) -> Option < MovePathIndex > { self . locals [local] } # [doc = " An enumerated iterator of `local`s and their associated"] # [doc = " `MovePathIndex`es."] pub fn iter_locals_enumerated (& self ,) -> impl DoubleEndedIterator < Item = (Local , MovePathIndex) > { self . locals . iter_enumerated () . filter_map (| (l , & idx) | Some ((l , idx ?))) } }}}
mkitem!{mkimpl!{impl < 'tcx > MoveData < 'tcx > { pub fn gather_moves (body : & Body < 'tcx > , tcx : TyCtxt < 'tcx > , filter : impl Fn (Ty < 'tcx >) -> bool ,) -> MoveData < 'tcx > { builder :: gather_moves (body , tcx , filter) } # [doc = " For the move path `mpi`, returns the root local variable that starts the path."] # [doc = " (e.g., for a path like `a.b.c` returns `a`)"] pub fn base_local (& self , mut mpi : MovePathIndex) -> Local { loop { let path = & self . move_paths [mpi] ; if let Some (l) = path . place . as_local () { return l ; } mpi = path . parent . expect ("root move paths should be locals") ; } } pub fn find_in_move_path_or_its_descendants (& self , root : MovePathIndex , pred : impl Fn (MovePathIndex) -> bool ,) -> Option < MovePathIndex > { if pred (root) { return Some (root) ; } self . move_paths [root] . find_descendant (& self . move_paths , pred) } }}}